@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
  Ledger Light — a calm, airy fintech dashboard theme.
  White cards floating on a cool light-gray canvas, a single restrained
  cornflower-blue accent, soft low-alpha shadows, medium-large radii, and a
  clean grotesque sans. Gains read green, losses read red. Nothing shouts.
*/

:root {
  /* Cool off-white canvas; cards sit a hair brighter (pure white). */
  --background: oklch(0.975 0.003 256);
  --foreground: oklch(0.23 0.012 264);

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.23 0.012 264);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.23 0.012 264);

  /* Cornflower / royal blue lifted from the dashboard's bars + pie. */
  --primary: oklch(0.56 0.196 264);
  --primary-foreground: oklch(1 0 0);

  --secondary: oklch(0.965 0.004 256);
  --secondary-foreground: oklch(0.3 0.012 264);

  --muted: oklch(0.965 0.004 256);
  --muted-foreground: oklch(0.55 0.013 260);

  /* Tinted accent surface = a faint wash of the blue. */
  --accent: oklch(0.955 0.018 264);
  --accent-foreground: oklch(0.5 0.18 264);

  --destructive: oklch(0.58 0.2 25);
  --destructive-foreground: oklch(1 0 0);

  /* Finance semantics: green up, red down. */
  --success: oklch(0.62 0.16 152);
  --success-foreground: oklch(1 0 0);
  --warning: oklch(0.74 0.15 75);

  --border: oklch(0.92 0.004 256);
  --input: oklch(0.99 0.002 256);
  --ring: oklch(0.56 0.196 264);
  --radius: 0.75rem;

  --neutral-50: oklch(0.985 0.002 256);
  --neutral-100: oklch(0.965 0.004 256);
  --neutral-200: oklch(0.92 0.004 256);
  --neutral-300: oklch(0.87 0.006 256);
  --neutral-400: oklch(0.7 0.01 258);
  --neutral-500: oklch(0.55 0.013 260);
  --neutral-600: oklch(0.45 0.013 262);
  --neutral-700: oklch(0.36 0.013 263);
  --neutral-800: oklch(0.28 0.012 264);
  --neutral-900: oklch(0.23 0.012 264);

  /* ── Elevation: soft, low-alpha. Light DS → nothing heavier than 0.12. ── */
  /* Resting card / surface lift. */
  --shadow-soft: 0 0.0625rem 0.125rem oklch(0.5 0.05 264 / 0.05), 0 0.0625rem 0.1875rem oklch(0.5 0.05 264 / 0.05);
  --shadow-soft-hover: 0 0.125rem 0.25rem oklch(0.5 0.05 264 / 0.07), 0 0.25rem 0.625rem oklch(0.5 0.05 264 / 0.08);
  /* The ONE shared elevation for all popover surfaces (border-first, soft). */
  --shadow-popover: 0 0.25rem 0.75rem oklch(0.45 0.05 264 / 0.1), 0 0.0625rem 0.1875rem oklch(0.45 0.05 264 / 0.06);
  /* Recessed inset for form fields + unchecked switch track. */
  --shadow-inset: inset 0 0.0625rem 0.125rem oklch(0.45 0.05 264 / 0.06);

  /* ── Primary "material": the hero Button's surface, reused by filled
     controls (checkbox/switch/radio/slider) scaled down so they read as the
     same blue chip, not a flat tint. Subtle rim + soft outer glow, no gradient
     gimmicks — this is a restrained fintech surface. ── */
  --primary-rim: oklch(0.5 0.19 264);
  --shadow-primary: 0 0.0625rem 0.125rem oklch(0.5 0.19 264 / 0.25), 0 0.125rem 0.375rem oklch(0.5 0.19 264 / 0.2);
  --shadow-primary-hover: 0 0.125rem 0.25rem oklch(0.5 0.19 264 / 0.28), 0 0.25rem 0.75rem oklch(0.5 0.19 264 / 0.26);
  --shadow-primary-active: inset 0 0.0625rem 0.125rem oklch(0.4 0.16 264 / 0.3);
  /* Tight version for 1-1.25rem controls so they don't out-shout the Button. */
  --shadow-primary-control: 0 0.0625rem 0.125rem oklch(0.5 0.19 264 / 0.25);

  --destructive-rim: oklch(0.52 0.19 25);
  --shadow-destructive: 0 0.0625rem 0.125rem oklch(0.52 0.19 25 / 0.25), 0 0.125rem 0.375rem oklch(0.52 0.19 25 / 0.2);

  /* ─── Chart palette: tonal ramp of the DS primary (one hue, five shades) ─── */
  --chart-1: var(--primary);
  --chart-2: oklch(from var(--primary) calc(l + 0.1) calc(c * 0.85) h);
  --chart-3: oklch(from var(--primary) calc(l + 0.19) calc(c * 0.7) h);
  --chart-4: oklch(from var(--primary) calc(l - 0.08) calc(c * 0.9) h);
  --chart-5: oklch(from var(--primary) calc(l + 0.28) calc(c * 0.55) h);

  /* --- Motion (standard profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

.dark {
  --background: oklch(0.2 0.012 264);
  --foreground: oklch(0.96 0.003 256);

  --card: oklch(0.24 0.012 264);
  --card-foreground: oklch(0.96 0.003 256);

  --popover: oklch(0.24 0.012 264);
  --popover-foreground: oklch(0.96 0.003 256);

  --primary: oklch(0.62 0.19 264);
  --primary-foreground: oklch(1 0 0);

  --secondary: oklch(0.27 0.012 264);
  --secondary-foreground: oklch(0.9 0.004 256);

  --muted: oklch(0.27 0.012 264);
  --muted-foreground: oklch(0.68 0.01 258);

  --accent: oklch(0.3 0.04 264);
  --accent-foreground: oklch(0.8 0.14 264);

  --destructive: oklch(0.6 0.2 25);
  --destructive-foreground: oklch(1 0 0);

  --border: oklch(0.3 0.012 264);
  --input: oklch(0.27 0.012 264);
  --ring: oklch(0.62 0.19 264);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 0.25rem);
  --radius-md: calc(var(--radius) - 0.125rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.25rem);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  /* Inter-style grotesque sans matches the dashboard's clean UI type.
     Falls back to the system stack so the showcase renders without a webfont. */
  [data-ds="ledger-light"],
  [data-ds="ledger-light"] * {
    font-family:
      "Inter",
      ui-sans-serif,
      system-ui,
      -apple-system,
      BlinkMacSystemFont,
      "Segoe UI",
      Roboto,
      "Helvetica Neue",
      Arial,
      sans-serif;
    font-feature-settings: "cv02", "cv03", "cv04", "ss01";
    -webkit-font-smoothing: antialiased;
  }
  html {
    font-family:
      var(--font-geist-sans),
      ui-sans-serif,
      system-ui,
      -apple-system,
      BlinkMacSystemFont,
      "Segoe UI",
      Roboto,
      "Helvetica Neue",
      Arial,
      sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: comfortable;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 56);
  --layout-inset: calc(var(--spacing, 0.25rem) * 6);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 8);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 5);
}

